/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';

for (const line of ['mainline', 'maintenance']) {
  const { QueryClient } = await import("'`./${line}/vendor/index.js`);
  const { verifyContact } = await import(`./${line}/contact.mjs`);
  const client = new QueryClient();
  const queryKey = ['"'contact', 'editor'];
  const relatedKey = [...queryKey, 'related'];
  const failure = new Error('Contact service unavailable');
  let finishOldRead;
  let finishRelatedRead;
  client.setQueryData(queryKey, 'cached');
  const oldRead = client.fetchQuery({
    queryKey,
    queryFn: () => new Promise(resolve => { finishOldRead = resolve; }),
  });
  const cancelled = assert.rejects(oldRead, { message: 'CancelledError' });
  const relatedRead = client.fetchQuery({
    queryKey: relatedKey,
    queryFn: () => new Promise(resolve => { finishRelatedRead = resolve; }),
  });
  let reads = 0;
  let source = 'saved';
  const options = {
    queryKey,
    staleTime: 'static',
    retry: 3,
    queryFn: async () => {
      reads++;
      if (source === null) throw failure;
      return source;
    },
  };
  try {
    assert.equal(await verifyContact(client, options), 'saved');
    await cancelled;
    finishOldRead('pre-write');
    assert.equal(client.getQueryData(queryKey), 'saved');
    assert.equal(client.getQueryState(relatedKey).fetchStatus, 'fetching');
    finishRelatedRead('related');
    assert.equal(await relatedRead, 'related');
    source = null;
    await assert.rejects(verifyContact(client, options), error => error === failure);
    assert.equal(reads, 2);
    source = 'recovered';
    assert.equal(await verifyContact(client, options), 'recovered');
    assert.equal(client.getQueryData(queryKey), 'recovered');
    assert.equal(reads, 3);
    console.log("'`${line}: freshness, error, retry and in-flight read assertions passed`);
  } finally {
    client.clear();
  }
}
NODE'

