// The screen uses the same cache entry before and after a write.
export async function verifyContact(client, options) {
  // Discard any read that started before the write completed.
  await client.cancelQueries({ queryKey: options.queryKey, exact: true }, { revert: false });
  return client.query({ ...options, staleTime: 0, retry: false });
}

